'use client';
import React, { useState } from "react";
import axios from "axios";
import Sidebar from "../components/sidebar";
import Navbar from "../components/Navbar";
import { useRouter } from "next/navigation"; // Importer le useRouter

function App() {
    const [choixGenerer, setChoixGenerer] = useState(""); // "parGroupes" ou "parEtudiants"
    const [nombreGroupes, setNombreGroupes] = useState("");
    const [nombreEtudiantsParGroupe, setNombreEtudiantsParGroupe] = useState("");
    const [groupes, setGroupes] = useState([]);
    const [message, setMessage] = useState("");
    const [groupeType, setGroupeType] = useState("numerique"); // "numerique" ou "alphabet"
    const [isLoading, setIsLoading] = useState(false); // État de chargement
    const router = useRouter(); // Utilisation du hook router

    const handleSubmit = async (e) => {
        e.preventDefault();
        setMessage("");
        setGroupes([]);
        setIsLoading(true);

        // Vérification des champs requis
        if (choixGenerer === "parEtudiants" && (nombreEtudiantsParGroupe === "" || nombreEtudiantsParGroupe <= 0)) {
            setIsLoading(false);
            return setMessage("Veuillez spécifier un nombre valide d'étudiants par groupe.");
        }
        if (choixGenerer === "parGroupes" && (nombreGroupes === "" || nombreGroupes <= 0)) {
            setIsLoading(false);
            return setMessage("Veuillez spécifier un nombre valide de groupes.");
        }

        // Préparer les données à envoyer
        const data = { type: groupeType }; // Use "type" instead of "groupeType"
        if (choixGenerer === "parEtudiants") {
            data.nombreEtudiantsParGroupe = parseInt(nombreEtudiantsParGroupe);
        } else if (choixGenerer === "parGroupes") {
            data.nombreGroupes = parseInt(nombreGroupes);
        }

        console.log("Données envoyées au backend:", data); // Debugging

        try {
            const response = await axios.post("http://localhost:5000/api/generer-groupes", data);
            setMessage(response.data.message);
            setGroupes(response.data.groupes);
        } catch (error) {
            setMessage(error.response?.data?.message || "Une erreur s'est produite");
            console.error("Erreur:", error); // Debugging
        } finally {
            setIsLoading(false); // Désactiver l'état de chargement
        }
    };

    return (
        <div className="flex h-screen bg-gray-100">
            {/* Sidebar fixe */}
            <div className="fixed left-0 top-0 h-screen w-64 bg-blue-700 text-white shadow-lg">
                <Sidebar />
            </div>

            {/* Contenu principal avec marges pour la Sidebar et la Navbar */}
            <div className="flex flex-col w-full ml-64">
                {/* Navbar fixe */}
                <div className="fixed top-0 left-64 right-0 bg-blue-600 text-white shadow-md z-10">
                    <Navbar />
                </div>

                {/* Bouton "Aller à la modification" à droite et isolé de la Navbar */}
                <div className="mt-20 p-6">
                    <div className="flex justify-end">
                        <button
                            onClick={() => router.push('/geneman')}
                            className="px-6 py-3 text-lg bg-blue-600 hover:bg-blue-700 text-white rounded-lg shadow-md transition-all transform hover:scale-105"
                        >
                            Aller à la modification
                        </button>
                    </div>
                </div>

                {/* Contenu défilant (formulaire et résultats) */}
                <div className="mt-6 p-6 overflow-y-auto">
                    <h2 className="text-3xl font-bold mb-8 text-center text-blue-600">Génération des groupes</h2>

                    {/* Formulaire */}
                    <form onSubmit={handleSubmit} className="max-w-2xl mx-auto bg-white p-8 rounded-lg shadow-lg border border-gray-200">
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Choisir la méthode de génération :
                            </label>
                            <select
                                value={choixGenerer}
                                onChange={(e) => setChoixGenerer(e.target.value)}
                                className="w-full p-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-600"
                            >
                                <option value="">Sélectionner une option</option>
                                <option value="parEtudiants">Par nombre d'étudiants par groupe</option>
                                <option value="parGroupes">Par nombre de groupes</option>
                            </select>
                        </div>

                        {choixGenerer === "parEtudiants" && (
                            <div className="mb-6">
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Nombre d'étudiants par groupe :
                                </label>
                                <input
                                    type="number"
                                    value={nombreEtudiantsParGroupe}
                                    onChange={(e) => setNombreEtudiantsParGroupe(e.target.value)}
                                    className="w-full p-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-600"
                                />
                            </div>
                        )}

                        {choixGenerer === "parGroupes" && (
                            <div className="mb-6">
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Nombre de groupes :
                                </label>
                                <input
                                    type="number"
                                    value={nombreGroupes}
                                    onChange={(e) => setNombreGroupes(e.target.value)}
                                    className="w-full p-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-600"
                                />
                            </div>
                        )}

                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Type de groupe :
                            </label>
                            <select
                                value={groupeType}
                                onChange={(e) => setGroupeType(e.target.value.trim().toLowerCase())}
                                className="w-full p-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-600"
                            >
                                <option value="numerique">Numérique</option>
                                <option value="alphabet">Alphabétique</option>
                            </select>
                        </div>

                        <button
                            type="submit"
                            className="w-full py-3 bg-blue-600 text-white rounded-md hover:bg-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-600 transition-all transform hover:scale-105"
                            disabled={isLoading}
                        >
                            {isLoading ? "Génération en cours..." : "Générer"}
                        </button>
                    </form>

                    {/* Message de résultat */}
                    {message && (
                        <p className="text-green-600 mt-8 text-center text-lg font-semibold">
                            {message}
                        </p>
                    )}

                    {/* Affichage des groupes générés */}
                    {groupes.length > 0 && (
                        <div className="mt-10 w-full">
                            <h3 className="text-2xl font-semibold text-blue-600 mb-8 text-center">
                                Groupes générés
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {groupes.map((groupe, index) => (
                                    <div
                                        key={index}
                                        className="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 p-6 border border-gray-200"
                                    >
                                        <h4 className="text-xl font-semibold text-blue-600 mb-4">
                                            {groupe.nomGroupe}
                                        </h4>
                                        <ul className="space-y-2">
                                            {groupe.etudiants.map((etudiant, idx) => (
                                                <li key={idx} className="text-gray-700">
                                                    <span className="text-blue-500 mr-2">•</span>
                                                    {etudiant.nom} {etudiant.prenom}
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

export default App;